// Contract bytecodes for deployment
export const MASP_VERIFIER_BYTECODE = '' as `0x${string}`;

export const MASP_POOL_BYTECODE = '' as `0x${string}`;

// Storage key for deployed contract addresses
const STORAGE_KEY = 'masp_deployed_contracts';

interface DeployedContracts {
  verifier?: `0x${string}`;
  pool?: `0x${string}`;
}

// Get deployed contracts from localStorage
export function getDeployedContracts(chainId: number): DeployedContracts {
  try {
    const stored = localStorage.getItem(`${STORAGE_KEY}_${chainId}`);
    if (stored) {
      return JSON.parse(stored);
    }
  } catch {
    // Ignore parse errors
  }
  return {};
}

// Save deployed contracts to localStorage
export function saveDeployedContracts(chainId: number, contracts: DeployedContracts): void {
  const existing = getDeployedContracts(chainId);
  const updated = { ...existing, ...contracts };
  localStorage.setItem(`${STORAGE_KEY}_${chainId}`, JSON.stringify(updated));
}

// Get MASP Pool address (from localStorage or defaults)
export function getMaspPoolAddress(chainId: number): `0x${string}` | undefined {
  // First check localStorage for deployed contract
  const deployed = getDeployedContracts(chainId);
  if (deployed.pool && deployed.pool !== '0x0000000000000000000000000000000000000000') {
    return deployed.pool;
  }

  // Fall back to defaults
  const defaults: Record<number, `0x${string}`> = {
    31337: '0x5FbDB2315678afecb367f032d93F642f64180aa3', // Localhost
  };

  return defaults[chainId];
}

// Get MASP Verifier address (from localStorage)
export function getMaspVerifierAddress(chainId: number): `0x${string}` | undefined {
  const deployed = getDeployedContracts(chainId);
  return deployed.verifier;
}

// Get default token address for a chain
export function getDefaultTokenAddress(chainId: number): `0x${string}` {
  const defaults: Record<number, `0x${string}`> = {
    11155111: SEPOLIA_WETH_ADDRESS, // Sepolia WETH
    1: '0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2', // Mainnet WETH
    31337: '0x5FbDB2315678afecb367f032d93F642f64180aa3', // Localhost (placeholder)
  };

  return defaults[chainId] || SEPOLIA_WETH_ADDRESS;
}
